import numpy as np
from PIL import Image
import zlib
from collections import defaultdict

def read_image(image_path):
    img = Image.open(image_path)
    return np.array(img)

def encode_image(image_array):
    rle_counts = {}
    height, width, _ = image_array.shape
    for i in range(height):
        for j in range(width):
            pixel = image_array[i, j]
            if pixel not in rle_counts:
                rle_counts[pixel] = 1
            else:
                rle_counts[pixel] += 1

    rle_string = ''
    prev_pixel = None
    count = 0
    for pixel in rle_counts.keys():
        if prev_pixel is not None and pixel != prev_pixel:
            rle_string += str(count) + 'x' + str(prev_pixel) + ','
            count = 1
        else:
            count += 1

        prev_pixel = pixel
    rle_string += str(count) + 'x' + str(pixel)

    return rle_string

def jpeg_compress(image_array):
    height, width, _ = image_array.shape
    chroma_subsampled_image = np.zeros((height // 2, width // 2, 3))
    for i in range(0, height, 2):
        for j in range(0, width, 2):
            chroma_subsampled_image[i // 2, j // 2] = (image_array[i, j][0] + image_array[i + 1, j][0]) / 2, \
                                                      (image_array[i, j][1] + image_array[i + 1, j][1]) / 2, \
                                                      (image_array[i, j][2] + image_array[i + 1, j][2]) / 2
    return chroma_subsampled_image

def huffman_encoding(message):
    frequency = defaultdict(int)
    for char in message:
        frequency[char] += 1

    max_freq = max(frequency.values())
    min_freq = min(frequency.values())

    def calculate_code(code, freq):
        if freq == min_freq:
            return code
        for char, ch_freq in frequency.items():
            if ch_freq == freq:
                return code + '0'
        return code + '1'

    huffman_dict = {}
    codes = []
    current_code = ''
    sorted_frequency = sorted(frequency.items(), key=lambda x: x[1], reverse=True)
    for i, (char, freq) in enumerate(sorted_frequency):
        code = calculate_code(current_code, freq)
        huffman_dict[char] = code
        if freq != max_freq:
            current_code += '1'

    return huffman_dict

def main():
    image_path = 'image.jpg'
    image_array = read_image(image_path)

    rle_string = encode_image(image_array)
    print("Run-Length Encoding:", rle_string)

    chroma_subsampled_image = jpeg_compress(image_array)
    print("\nChroma Subsampling Image (JPEG):")
    print(chroma_subsampled_image.shape)
    print(chroma_subsampled_image)

    huffman_dict = huffman_encoding(rle_string)
    encoded_message = ''.join(huffman_dict.get(char, '') for char in rle_string)
    print("\nHuffman Encoding Message:")
    print(encoded_message)

if __name__ == "__main__":
    main()
